('o8-A3-3', 'q8000001-0000-0000-0000-000000000003', 'Membaca data', 0, 'Keliru. Membaca data adalah operasi Read.'),
('o8-A3-4', 'q8000001-0000-0000-0000-000000000003', 'Mengurutkan data', 0, 'Keliru. Pengurutan data adalah operasi sorting/query filtering.'),
