INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000008-0000-0000-0000-000000000001', 'q8000002-0000-0000-0000-000000000001', 'Integrasi data dinamis adalah proses menghubungkan aplikasi dengan sumber data sehingga data dapat dibaca, ditampilkan, ditambahkan, dan diperbarui secara real-time atau sesuai kebutuhan aplikasi.', ARRAY['data dinamis', 'database', 'read', 'write', 'sinkronisasi data']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Data aplikasi dapat berubah tanpa mengubah kode (belum menjelaskan hubungan dengan database dan operasi read/write)","9":"Aplikasi terhubung dengan database sehingga data dapat berubah secara otomatis","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000002', 'q8000002-0000-0000-0000-000000000002', 'Read adalah proses mengambil atau menampilkan data dari database, sedangkan Write adalah proses menyimpan atau mengubah data ke database.', ARRAY['read', 'fetching', 'write', 'insert', 'database']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan Read dan Write adalah operasi data tanpa menjelaskan perbedaannya","8":"Read melihat data dan Write membuat data (belum menjelaskan hubungan dengan database)","9":"Read mengambil data dan Write menyimpan data","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000003', 'q8000002-0000-0000-0000-000000000003', 'BaaS adalah layanan backend siap pakai yang menyediakan database, autentikasi, API, dan layanan lainnya sehingga developer tidak perlu membangun backend dari nol.', ARRAY['baas', 'backend', 'layanan siap pakai', 'database', 'api']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000004', 'q8000002-0000-0000-0000-000000000004', 'Karena Supabase menyediakan database PostgreSQL, autentikasi, API otomatis, storage, dan fitur backend lainnya yang dapat langsung digunakan oleh developer.', ARRAY['supabase', 'postgresql', 'api', 'autentikasi', 'backend']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000005', 'q8000002-0000-0000-0000-000000000005', 'UI State digunakan untuk menggambarkan kondisi aplikasi kepada pengguna seperti idle, loading, success, error, dan empty sehingga pengguna memahami status sistem.', ARRAY['ui state', 'loading', 'success', 'error', 'empty']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000006', 'q8000004-0000-0000-0000-000000000001', 'Loading State adalah kondisi ketika aplikasi sedang memproses atau mengambil data sehingga pengguna perlu menunggu hasilnya.', ARRAY['loading', 'mengambil data', 'proses', 'menunggu']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000007', 'q8000004-0000-0000-0000-000000000002', 'Empty State membantu pengguna memahami bahwa data belum tersedia dan memberikan arahan tindakan yang dapat dilakukan selanjutnya.', ARRAY['empty state', 'data kosong', 'arahan pengguna']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000008', 'q8000004-0000-0000-0000-000000000003', 'Debounce digunakan untuk menunda eksekusi request hingga pengguna berhenti mengetik sehingga mengurangi request yang tidak diperlukan ke server.', ARRAY['debounce', 'pencarian', 'mengurangi request', 'efisiensi']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Debounce digunakan pada search (terlalu umum)","8":"Debounce membuat pencarian lebih cepat (belum menjelaskan mekanisme penundaan request)","9":"Debounce mengurangi jumlah request saat pengguna mengetik","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000009', 'q8000004-0000-0000-0000-000000000004', 'AbortController digunakan untuk membatalkan request yang tidak lagi diperlukan sehingga mencegah race condition dan pemborosan sumber daya.', ARRAY['abortcontroller', 'membatalkan request', 'race condition']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000010', 'q8000004-0000-0000-0000-000000000005', 'RLS adalah mekanisme keamanan yang mengatur siapa yang dapat melihat, mengubah, atau menghapus data pada tingkat baris data tertentu di database.', ARRAY['rls', 'keamanan', 'akses data', 'row level']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"RLS adalah fitur Supabase (tidak menjelaskan fungsi sebenarnya)","8":"RLS digunakan untuk keamanan database (belum menjelaskan kontrol akses pada tingkat baris data)","9":"RLS membatasi akses data berdasarkan aturan tertentu","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000011', 'q8000006-0000-0000-0000-000000000001', 'Validasi memastikan data yang masuk sesuai aturan sehingga mengurangi kesalahan, menjaga kualitas data, dan meningkatkan keamanan aplikasi.', ARRAY['validasi', 'data benar', 'aturan', 'keamanan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000012', 'q8000006-0000-0000-0000-000000000002', 'Validasi memeriksa apakah data sesuai aturan, sedangkan sanitasi membersihkan atau memodifikasi data agar aman digunakan sistem.', ARRAY['validasi', 'sanitasi', 'aturan data', 'keamanan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000013', 'q8000006-0000-0000-0000-000000000003', 'DOMPurify membersihkan input HTML yang berpotensi mengandung script berbahaya sehingga membantu mencegah serangan XSS.', ARRAY['dompurify', 'xss', 'sanitasi html', 'keamanan']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Hanya menyebutkan ide umum tanpa kedalaman konsep sesuai materi","8":"Sekitar 60% konsep benar, namun penjelasan masih terlalu umum atau kurang lengkap","9":"Konsep inti benar, namun terdapat 1 unsur penjelas penting yang belum disebutkan","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000014', 'q8000006-0000-0000-0000-000000000004', 'Skeleton Loading memberikan placeholder visual sementara saat data sedang dimuat sehingga pengguna merasa aplikasi lebih responsif.', ARRAY['skeleton loading', 'placeholder', 'loading', 'ux']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"Skeleton adalah animasi loading (terlalu sempit dan kurang menjelaskan fungsinya)","8":"Skeleton digunakan saat loading (belum menjelaskan manfaat terhadap pengalaman pengguna)","9":"Skeleton Loading menampilkan tampilan sementara saat data dimuat","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb),
('er-0000008-0000-0000-0000-000000000015', 'q8000006-0000-0000-0000-000000000005', 'README berfungsi sebagai dokumentasi proyek, sedangkan schema.sql mendokumentasikan struktur database sehingga proyek lebih mudah dipahami, dijalankan, dan dikembangkan oleh tim lain.', ARRAY['readme', 'dokumentasi', 'schema.sql', 'struktur database', 'kolaborasi']::text[], '{"0":"Konsep keliru, jawaban kosong, atau mayoritas kata kunci utama tidak terpenuhi","7":"README dan schema.sql adalah file proyek (terlalu umum)","8":"Keduanya digunakan untuk dokumentasi proyek (belum menjelaskan fungsi spesifik masing-masing dokumen)","9":"README menjelaskan proyek dan schema.sql menjelaskan database","10":">= 80% kata kunci utama muncul dan konsep inti dijelaskan secara tepat"}'::jsonb);
